describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, plus fixed 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (Cart clamps later)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Each capped at 1000 individually, but sum mode sums raw: min(600,1000)+min(600,1000)=1200
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies each policy to the remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 1000 = 100, remaining 900
      // Second: 10% of 900 = 90, remaining 810
      // Total discount = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("caps each step at remaining", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // First: min(800, 1000) = 800, remaining 200
      // Second: min(800, 200) = 200, remaining 0
      // Total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters — bigger discount first yields same total discount ceiling", () => {
      const a = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(20)],
        "chain",
      );
      const b = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(20), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // a: 50% of 1000=500, then 20% of 500=100 → 600
      // b: 20% of 1000=200, then 50% of 800=400 → 600
      expect(a.computeDiscountCents(1000)).toBe(600);
      expect(b.computeDiscountCents(1000)).toBe(600);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode when mode is omitted", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    // sum: 100 + 200 = 300
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

