        { upToGrams: 500, costCents: 300 },
      ]);
      expect(unsorted.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
    });

    it("sums weight across multiple lines with quantity", () => {
      // 2 items of 300g each = 600g → second bracket (600)
      expect(calc.computeShippingCents([makeLine("a", 300, 2)], 1000)).toBe(600);
    });

    it("treats missing weightGrams as 0", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
      ];
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });
  });
});

