import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000, weightGrams: 200 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  describe("add", () => {
    it("adds a product to the cart", () => {
      cart.add(productA, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities for the same product", () => {
      cart.add(productA, 1);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(4);
    });

    it("rejects non-positive quantity", () => {
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const badProduct = { ...productA, unitPriceCents: -1 };
      expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("returns true when product exists", () => {
      cart.add(productA, 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product", () => {
      expect(cart.remove("unknown")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of an existing product", () => {
      cart.add(productA, 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is 0", () => {
      cart.add(productA, 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      expect(() => cart.updateQuantity("unknown", 1)).toThrow("not in the cart");
    });

    it("rejects negative quantity", () => {
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      cart.add(productA, 1);
      cart.add(productB, 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that cannot mutate internal state", () => {
      cart.add(productA, 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 999;
      expect(cart.itemCount).toBe(2);
    });
  });
});

describe("Cart — pricing pipeline", () => {
  it("computes correct totals with default (no-op) policies", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(4000);
  });

  it("applies discount → tax on discounted subtotal → shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(150),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(800),
    };

    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator, region: "US-CA" });
    cart.add(productA, 2); // subtotal = 2000

    const totals = cart.totals();

    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(500);
    // Tax is computed on discounted subtotal (2000 - 500 = 1500)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1500, "US-CA");
    expect(totals.taxCents).toBe(150);
    // Shipping receives lines and discounted subtotal
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      1500,
    );
    expect(totals.shippingCents).toBe(800);
    // total = discountedSubtotal + tax + shipping = 1500 + 150 + 800
    expect(totals.totalCents).toBe(2450);
  });

  it("clamps discount to [0, subtotal]", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1); // 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped to subtotal
    expect(totals.totalCents).toBe(0); // no tax, no shipping
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("empty cart returns all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("defaults region to US", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });
});

describe("Cart — async checkout()", () => {
  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 1); // original: 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, availableQuantity: 2, reason: "low stock" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(2);
      expect(err.message).toBe("low stock");
    }
  });

  it("throws InventoryError on partial-stock denial (available < requested)", async () => {
    const cart = new Cart();
    cart.add(productA, 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 3 }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("succeeds when inventory check passes", async () => {
    const cart = new Cart();
    cart.add(productA, 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "FR" });
    cart.add(productA, 1); // subtotal 1000, discount 200 → taxable 800

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2),
    };

    const result = await cart.checkout({ asyncTaxProvider });
    // tax: 20% of 800 = 160
    expect(result.totals.taxCents).toBe(160);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    expect(result.totals.shippingCents).toBe(500);
    // total = 800 + 160 + 500
    expect(result.totals.totalCents).toBe(1460);
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({ region: "US-CA" });
    cart.add(productA, 2);
    cart.add(productB, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1200) // productA new price
        .mockResolvedValueOnce(2500), // productB new price
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };

    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    // subtotal: 1200*2 + 2500*1 = 4900
    expect(result.totals.subtotalCents).toBe(4900);
    // no discount policy → discount = 0, taxable = 4900
    // tax: 10% of 4900 = 490
    expect(result.totals.taxCents).toBe(490);
  });

  it("works with no collaborators (identity checkout)", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.totalCents).toBe(1000);
  });

  it("propagates priceFetcher error", async () => {
    const cart = new Cart();
    cart.add(productA, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };

    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
  });

  it("propagates asyncTaxProvider error", async () => {
    const cart = new Cart();
    cart.add(productA, 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
    };

    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service error");
  });
});

